import {createLeaveViews} from './leave-view.mjs';
import {leaveLabels} from './leave-contract.mjs';
import {correctionLabels,attendanceActions,approvalBlockers} from './attendance-contract.mjs';
export function createAttendanceView({api,h,heading,showPanel,localTime,writable,onEdit,onDecision,onLeaveEdit,onLeaveAction}){
 const $=s=>document.querySelector(s);let tab,identity,user,parent,request,offset=0,serial=0;
 const leaveViews=createLeaveViews({api,h,showPanel,localTime,writable,getUser:()=>user,onEdit:onLeaveEdit,onAction:onLeaveAction});
 const statuses=()=>Object.entries(tab==='leaves'?leaveLabels:correctionLabels).map(([key,label])=>`<option value="${key}">${h(label)}</option>`).join('')+'<option value="all">全部申请</option>';
 const hint=()=>tab==='leaves'?'请假按时间段涉及的日期筛选；待审核可修改或撤回，已批准请假由管理员说明原因后撤销。时间段暂不折算出勤天数或工资。':user.role==='admin'?'审核前对照原考勤及申请原因。原记录变化后，需要员工核对更新申请；驳回时说明原因。':'已有当天记录，请进入记录申请补正；申请提交后可在待审核状态修改，已处理的申请保留历史。';
 const fmt=v=>v?localTime(v):'未登记';
 function periodFacts(r){return `<dl class="record-facts">${[['工作日',r.work_date],['类型',r.kind==='studio'?'工作室':'历史外勤'],['原始上班',fmt(r.original_in)],['原始下班',fmt(r.original_out)],['核准上班',fmt(r.adjusted_in||r.original_in)],['核准下班',fmt(r.adjusted_out||r.original_out)]].map(([k,v])=>`<div><dt>${h(k)}</dt><dd>${h(v)}</dd></div>`).join('')}</dl>`;}
 async function detail(id,correction=false,historyOffset=0){
  await showPanel(correction?'补卡申请':'考勤记录',async signal=>{
   const [d,history]=await Promise.all([api.attendanceDetail(id,correction,signal),api.attendanceHistory(id,correction,historyOffset,signal)]),r=d.record,employee=user.role==='employee',stale=correction&&r.status==='pending'&&((d.period&&d.period.version!==r.period_version)||d.approvalBlocker);
   const actions=correction?(r.status==='pending'&&writable?(employee?`<button class="primary" data-attendance-edit="${h(id)}">核对并修改申请</button>`:`${!stale?`<button class="primary" data-attendance-decision="${h(id)}" data-decision="approved">批准</button>`:''}<button class="secondary" data-attendance-decision="${h(id)}" data-decision="rejected">驳回并说明</button>`):''):(employee&&writable&&(r.kind==='studio'||r.approval_status==='approved')?`<button class="secondary" data-attendance-period="${h(id)}" data-direction="in">申请补正上班</button><button class="secondary" data-attendance-period="${h(id)}" data-direction="out">申请补正下班</button>`:'');
   return `<div class="dialog-header"><h2>${h(r.memberName||'考勤记录')}</h2><button class="icon-button" data-attendance-close aria-label="关闭考勤详情">×</button></div>${correction?`<div class="detail-meta"><span class="type-tag">${h(correctionLabels[r.status])}</span><span>${r.direction==='in'?'上班':'下班'}补卡</span></div><p>申请时间：${h(fmt(r.proposed_at))}</p><p class="preserve-text">申请原因：${h(r.reason)}</p>${r.reviewed_at?`<p>审核时间：${h(fmt(r.reviewed_at))}</p><p class="preserve-text">审核说明：${h(r.review_note||'未填写')}</p>`:''}${stale?`<p class="planning-rule">${h(approvalBlockers[d.approvalBlocker]||approvalBlockers['source-changed'])}</p>`:''}${d.period?periodFacts(d.period):'<p class="muted">本申请用于补建缺失的上班记录，不推算下班时间。</p>'}`:periodFacts(r)}<div class="action-row">${actions}</div><h3>修改与审核历史</h3>${history.rows.map(e=>`<article class="observation"><b>${h(attendanceActions[e.action]||'考勤操作')}</b><p>${h(e.actor_name)} · ${h(fmt(e.created_at))}</p>${e.after_value.proposed_at?`<p>申请时间：${h(fmt(e.after_value.proposed_at))}</p>`:''}${e.after_value.reason?`<p class="preserve-text">${h(e.after_value.reason)}</p>`:''}${e.after_value.review_note?`<p class="preserve-text">审核说明：${h(e.after_value.review_note)}</p>`:''}${e.action==='correction-applied'?`<p>核准上班：${h(fmt(e.before_value?.adjusted_in||e.before_value?.original_in))} → ${h(fmt(e.after_value.adjusted_in||e.after_value.original_in))}</p><p>核准下班：${h(fmt(e.before_value?.adjusted_out||e.before_value?.original_out))} → ${h(fmt(e.after_value.adjusted_out||e.after_value.original_out))}</p>`:''}</article>`).join('')||'<p class="muted">暂无历史记录。</p>'}<div class="pager"><button class="secondary" data-attendance-detail="${h(id)}" data-correction="${correction}" data-history-offset="${Math.max(0,historyOffset-50)}" ${historyOffset===0?'disabled':''}>上一页</button><span>${history.total?historyOffset+1+'–'+(historyOffset+history.rows.length)+' / '+history.total:'0 条'}</span><button class="secondary" data-attendance-detail="${h(id)}" data-correction="${correction}" data-history-offset="${historyOffset+50}" ${historyOffset+history.limit>=history.total?'disabled':''}>下一页</button></div>`;
  });
 }
 async function load(){
  if(parent.aborted||!$('#attendance-results'))return;request?.abort();request=new AbortController();const signal=AbortSignal.any([parent,request.signal]),current=++serial;$('#attendance-results').textContent='正在读取考勤…';$('#attendance-prev').disabled=true;$('#attendance-next').disabled=true;
  try{
   const params={view:user.role==='admin'?'team':'own',from:$('#attendance-from').value,to:$('#attendance-to').value,offset},data=tab==='leaves'?await api.leaveList({...params,status:$('#attendance-status').value},signal):tab==='corrections'?await api.attendanceCorrections({...params,status:$('#attendance-status').value},signal):await api.attendance(params,signal);if(signal.aborted||current!==serial)return;
   if(!data.rows.length&&offset>0){offset=Math.max(0,offset-50);await load();return;}
   $('#attendance-results').innerHTML=data.rows.map(r=>tab==='leaves'?leaveViews.row(r):`<button class="asset-row" data-attendance-detail="${h(r.id)}" data-correction="${tab==='corrections'}"><span><b>${h(r.memberName||'本人记录')}</b><small>${tab==='corrections'?h(fmt(r.proposed_at)):h(r.work_date)}</small></span><span><b>${tab==='corrections'?`${r.direction==='in'?'上班':'下班'}补卡 · ${h(correctionLabels[r.status])}`:h(fmt(r.adjusted_in||r.original_in))}</b><small>${tab==='corrections'?h(r.reason):'下班 '+h(fmt(r.adjusted_out||r.original_out))}</small></span><span class="task-arrow">›</span></button>`).join('')||'<div class="empty"><h3>暂无符合条件的记录</h3><p>可调整日期或申请状态后再查看。</p></div>';
   $('#attendance-caption').textContent=data.total?`${offset+1}–${offset+data.rows.length} / ${data.total} 条`:'0 条记录';$('#attendance-prev').disabled=offset===0;$('#attendance-next').disabled=offset+data.limit>=data.total;
  }catch(e){if(!signal.aborted)$('#attendance-results').textContent=e.message;}
 }
 document.addEventListener('click',e=>{
  const d=e.target.closest('button[data-attendance-detail]'),edit=e.target.closest('button[data-attendance-edit]'),p=e.target.closest('button[data-attendance-period]'),decision=e.target.closest('button[data-attendance-decision]');
  if(e.target.closest('[data-attendance-close]'))$('#cloud-detail').close();
  if(d)detail(d.dataset.attendanceDetail,d.dataset.correction==='true',Number(d.dataset.historyOffset||0));
  if(edit)onEdit({id:edit.dataset.attendanceEdit});if(p)onEdit({periodId:p.dataset.attendancePeriod,direction:p.dataset.direction});if(decision)onDecision(decision.dataset.attendanceDecision,decision.dataset.decision);
 });
 return {async render(signal,who){
  user=who;parent=signal;if(identity!==user.id){identity=user.id;tab=user.role==='admin'?'corrections':'periods';}offset=0;
  $('#main').innerHTML=heading(user.role==='admin'?'考勤与请假审核':'我的考勤','原始打卡与审核后的核准时间分别保留，不自动决定工资。')+`<section class="work-panel module-panel"><div class="action-row"><button class="secondary" data-attendance-tab="periods" aria-pressed="${tab==='periods'}">考勤记录</button><button class="secondary" data-attendance-tab="corrections" aria-pressed="${tab==='corrections'}">${user.role==='admin'?'补卡审核':'我的补卡申请'}</button><button class="secondary" data-attendance-tab="leaves" aria-pressed="${tab==='leaves'}">${user.role==='admin'?'请假审核':'我的请假'}</button>${writable&&user.role==='employee'?'<button class="primary" data-leave-edit="">＋ 申请请假</button><button class="primary" id="attendance-missing">＋ 无原记录，申请补上班</button>':''}</div><div class="module-toolbar"><label>开始日期<input id="attendance-from" type="date"></label><label>结束日期<input id="attendance-to" type="date"></label><label id="attendance-status-label" ${tab!=='periods'?'':'hidden'}>申请状态<select id="attendance-status">${statuses()}</select></label></div><p class="muted" id="attendance-hint">${h(hint())}</p><div id="attendance-results"></div><div class="pager"><button class="secondary" id="attendance-prev">上一页</button><span id="attendance-caption"></span><button class="secondary" id="attendance-next">下一页</button></div></section>`;
  document.querySelectorAll('[data-attendance-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.attendanceTab;offset=0;$('#attendance-status-label').hidden=tab==='periods';$('#attendance-status').innerHTML=statuses();$('#attendance-hint').textContent=hint();document.querySelectorAll('[data-attendance-tab]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));load();});
  for(const id of ['attendance-from','attendance-to','attendance-status'])$('#'+id).onchange=()=>{offset=0;load();};$('#attendance-prev').onclick=()=>{offset=Math.max(0,offset-50);load();};$('#attendance-next').onclick=()=>{offset+=50;load();};$('#attendance-missing')?.addEventListener('click',()=>onEdit({}));signal.addEventListener('abort',()=>request?.abort(),{once:true});await load();
 }};
}
